    let f = clamp(1.0 - dist / coverR, 0.0, 1.0);
    let angle = (scaledA / 100.0) * 6.2831853 * scaledF * f;
    let c = cos(angle);
    let s = sin(angle);
    let rotated = vec2f(relUv.x * c - relUv.y * s, relUv.x * s + relUv.y * c);
    warpedUv = centerUv + rotated;
